const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '支点' }
    ];
  },
  render: function (input, metrics) {
    var w = (input.viewport && input.viewport.widthDu) || 800;
    var h = (input.viewport && input.viewport.heightDu) || 600;

    var paths = [];
    var children = [];

    function addPath(id, cmds, fill, sw) {
      paths.push({ id: id, commands: cmds });
      children.push({ type: 'path', pathId: id, fill: fill, stroke: { width: sw } });
    }
    function poly(pts, close) {
      var c = [['M', pts[0][0], pts[0][1]]];
      for (var i = 1; i < pts.length; i++) {
        c.push(['L', pts[i][0], pts[i][1]]);
      }
      if (close) { c.push(['Z']); }
      return c;
    }
    function seg(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    function head(x1, y1, x2, y2, len, wid) {
      var dx = x2 - x1, dy = y2 - y1;
      var d = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / d, uy = dy / d;
      var px = -uy, py = ux;
      var bx = x2 - ux * len, by = y2 - uy * len;
      return [['M', x2, y2],
              ['L', bx + px * wid / 2, by + py * wid / 2],
              ['L', bx - px * wid / 2, by - py * wid / 2],
              ['Z']];
    }
    function doubleArrow(x1, y1, x2, y2, len, wid) {
      var dx = x2 - x1, dy = y2 - y1;
      var d = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / d, uy = dy / d;
      var c = [['M', x1, y1], ['L', x2, y2]];
      c = c.concat(head(x1 + ux * len, y1 + uy * len, x1, y1, len, wid));
      c = c.concat(head(x2 - ux * len, y2 - uy * len, x2, y2, len, wid));
      return c;
    }

    var groundY = 0.86 * h;
    var xL = 0.10 * w;
    var xF = 0.70 * w;
    var xR = 0.85 * w;
    var yL = 0.52 * h;
    var yF = 0.72 * h;
    var yR = 0.77 * h;
    var th = Math.max(6, 0.022 * h);
    var yDim = 0.44 * h;

    var COL = {
      bar: '#5B6B7F',
      rock: '#9AA0A6',
      ful: '#37474F',
      gnd: '#26354A',
      dim: '#C0392B',
      ext: '#B0B7C0',
      force: '#1B5E20',
      text: '#1F2A37'
    };

    addPath('ground', seg(0, groundY, w, groundY), COL.gnd, Math.max(2, 0.004 * h));

    addPath('fulcrum', poly([
      [xF, yF],
      [xF - 0.055 * w, groundY],
      [xF + 0.055 * w, groundY]
    ], true), COL.ful, 2);

    var bdx = xR - xL, bdy = yR - yL;
    var bd = Math.sqrt(bdx * bdx + bdy * bdy) || 1;
    var nx = -bdy / bd, ny = bdx / bd;
    addPath('bar', poly([
      [xL + nx * th / 2, yL + ny * th / 2],
      [xR + nx * th / 2, yR + ny * th / 2],
      [xR - nx * th / 2, yR - ny * th / 2],
      [xL - nx * th / 2, yL - ny * th / 2]
    ], true), COL.bar, 2);

    addPath('rock', poly([
      [0.820 * w, groundY],
      [0.815 * w, 0.775 * h],
      [0.845 * w, 0.705 * h],
      [0.900 * w, 0.665 * h],
      [0.955 * w, 0.715 * h],
      [0.985 * w, 0.800 * h],
      [0.990 * w, groundY]
    ], true), COL.rock, 2);

    addPath('extL', seg(xL, yL - th * 0.5, xL, yDim - 0.012 * h), COL.ext, 1.5);
    addPath('extF', seg(xF, yF - th * 0.5, xF, yDim - 0.012 * h), COL.ext, 1.5);
    addPath('extR', seg(xR, yR - th * 0.5, xR, yDim - 0.012 * h), COL.ext, 1.5);

    var hl = 0.026 * w;
    var hw = 0.016 * w;
    addPath('armEffort', doubleArrow(xL, yDim, xF, yDim, hl, hw), COL.dim, 2);
    addPath('armLoad', doubleArrow(xF, yDim, xR, yDim, hl, hw), COL.dim, 2);

    var fx1 = xL - 0.085 * w;
    var fy1 = yL - 0.14 * h;
    var fx2 = xL - 0.012 * w;
    var fy2 = yL - 0.008 * h;
    var forceCmds = seg(fx1, fy1, fx2, fy2).concat(head(fx1, fy1, fx2, fy2, 0.035 * w, 0.024 * w));
    addPath('force', forceCmds, COL.force, 2);

    children.push({
      type: 'label', contentId: metrics[0].contentId,
      anchor: { x: (xL + xF) / 2, y: yDim - 0.03 * h },
      hAlign: 'center', vAlign: 'bottom', color: COL.text
    });
    children.push({
      type: 'label', contentId: metrics[1].contentId,
      anchor: { x: (xF + xR) / 2, y: yDim - 0.03 * h },
      hAlign: 'center', vAlign: 'bottom', color: COL.text
    });
    children.push({
      type: 'label', contentId: metrics[2].contentId,
      anchor: { x: xF - 0.075 * w, y: groundY - 0.045 * h },
      hAlign: 'right', vAlign: 'middle', color: COL.text
    });

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
